mapper.select:
SELECT  FROM agent_tool_approval_request
WHERE tenant_id=#{tenantId} AND user_id=#{userId} AND id > #{afterSequence}
  AND status='PENDING' AND deleted=0
ORDER BY id ASC LIMIT #{limit}

mapper.update:
UPDATE agent_tool_approval_request SET status='DECIDED',decision=#{decision},comment='TIMEOUT_DEFAULT',
  decided_by='system-timeout',decided_at=#{decidedAt},revision=revision+1,updated_at=#{decidedAt}
WHERE tenant_id=#{tenantId} AND approval_id=#{approvalId} AND status='PENDING' AND revision=#{revision} AND deleted=0
